PokegearRegion Pokegear_RegionFromCoords(u16 x, u16 y) {
    if (x > 21) {
        if (x == 25 && y == 8) {
            // Mt. Silver
            return POKEGEAR_REGION_JOHTO;
        } else if ((x == 28 && y == 6) || (x == 28 && y > 8 && y < 13)) {
            // Indigo Plateau or Victory Road
            return POKEGEAR_REGION_INDIGO;
        } else {
            return POKEGEAR_REGION_KANTO;
        }
    }

    return POKEGEAR_REGION_JOHTO;
}

modifiche_codice.sostituisci:
PokegearRegion Pokegear_RegionFromCoords(u16 x, u16 y) {
    // Trinacria (blocco 4.4, E-GFX-02): colonna >= 24 della matrice 0 = Sicilia orientale (lato Kanto),
    // il resto = Sicilia occidentale (lato Johto); niente casi speciali di Monte Argento e Altopiano Blu (trama R-09.6)
    if (x >= 24) {
        return POKEGEAR_REGION_KANTO;
    }
    return POKEGEAR_REGION_JOHTO;
}

